<!DOCTYPE html><html><head><meta charset="utf-8"><title>Purchase Invoice {{ $invoice->invoice_number }}</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.7/dist/css/bootstrap.min.css" rel="stylesheet"><style>@media print{.no-print{display:none}}body{padding:20px}</style></head><body><div class="container"><div class="d-flex justify-content-between mb-4"><div class="d-flex align-items-center gap-3"><img src="{{ $institute->logo_url }}" alt="{{ $institute->name }} Logo" style="max-height:60px; object-fit:contain;"><h3 class="mb-0">{{ $institute->name }}</h3></div><h4>PURCHASE INVOICE<br><small class="text-muted">{{ $invoice->invoice_number }}</small></h4></div><div class="row mb-4"><div class="col-6"><strong>Supplier:</strong><br>{{ $invoice->supplier?->name }}<br>{{ $invoice->supplier?->address }}<br>{{ $invoice->supplier?->phone }}<br>{{ $invoice->supplier?->email }}</div><div class="col-6 text-end"><p><strong>Date:</strong> {{ $invoice->invoice_date->format('Y-m-d') }}<br><strong>Due:</strong> {{ $invoice->due_date?->format('Y-m-d') ?? '—' }}<br><strong>Status:</strong> {{ ucfirst($invoice->status) }}<br><strong>PO:</strong> {{ $invoice->purchaseOrder?->order_number ?? '—' }}</p></div></div><table class="table table-bordered"><thead><tr><th>#</th><th>Description</th><th class="text-end">Qty</th><th class="text-end">Unit Price</th><th class="text-end">Discount</th><th class="text-end">Tax</th><th class="text-end">Total</th></tr></thead><tbody>@foreach($invoice->items as $idx=>$line)<tr><td>{{ $idx+1 }}</td><td>{{ $line->description }}</td><td class="text-end">{{ number_format($line->quantity,2) }}</td><td class="text-end">{{ number_format($line->unit_price,2) }}</td><td class="text-end">{{ number_format($line->discount_amount,2) }}</td><td class="text-end">{{ number_format($line->tax_amount,2) }}</td><td class="text-end">{{ number_format($line->line_total,2) }}</td></tr>@endforeach</tbody><tfoot><tr><th colspan="6" class="text-end">Subtotal</th><th class="text-end">{{ number_format($invoice->subtotal,2) }}</th></tr><tr><th colspan="6" class="text-end">Discount</th><th class="text-end">-{{ number_format($invoice->discount_amount,2) }}</th></tr><tr><th colspan="6" class="text-end">Tax</th><th class="text-end">{{ number_format($invoice->tax_amount,2) }}</th></tr><tr><th colspan="6" class="text-end">Grand Total</th><th class="text-end">{{ number_format($invoice->grand_total,2) }}</th></tr><tr><th colspan="6" class="text-end">Paid</th><th class="text-end">{{ number_format($invoice->paid_amount,2) }}</th></tr><tr><th colspan="6" class="text-end">Due</th><th class="text-end">{{ number_format($invoice->due_amount,2) }}</th></tr></tfoot></table>@if($invoice->notes)<p><strong>Notes:</strong> {{ $invoice->notes }}</p>@endif<div class="no-print mt-4"><button onclick="window.print()" class="btn btn-primary">Print</button> <a href="{{ route('purchase.invoices.show',$invoice) }}" class="btn btn-outline-secondary">Back</a></div></div></body></html>

